# One-loop running of alpha_s (QCD), illustrative
import math
def alpha_s(Q, Lambda=0.2, nf=5):
    b0 = 11 - 2*nf/3
    return 4*math.pi/(b0*math.log((Q/Lambda)**2))
for Q in [2, 10, 91.2, 1000]:
    print(f"Q={Q:>7} GeV  alpha_s~{alpha_s(Q):.3f}")
print("Falls with energy: asymptotic freedom.")
